For any $\overline{\varepsilon}, \hbar \in {\mathbb{C}}$ and $\partial_w = \frac{\partial}{\partial w}$, the Nazarov--Sklyanin Lax operator ${\mathcal{L}}$ \textnormal{\cite{NaSk2}} is the graded linear operator ${\mathcal{L}} \colon F[w] \rightarrow F[w]$ in the graded polynomial ring $F[w]$ in {(\ref{HDefinition})} defined by
\begin{equation} \label{PresentationOfL} {\mathcal{L}} = \overline{\varepsilon} w \partial_w + \sum_{k=1}^{\infty} V_{-k} w^k + \sum_{k=1}^{\infty} V_k\pi w^{-k} \end{equation}
for $V_{-k}$ in {(\ref{VNegativeKDefinition})}, $\pi$ in {(\ref{SzegoProjectionFormula})}. Below, we may write ${\mathcal{L}} = {\mathcal{L}}_{\overline{\varepsilon},\hbar}$ to emphasize that $V_{-k}$ depends on $\hbar$.

For $\lambda$ in {(\ref{DefinitionDLambda})}, define the addable and removable corner sets by
 \begin{gather} \label{AddSetFormula}
 \mathcal{A}_{\lambda} = \big\{ s \in {\mathbb{N}}^2 \colon s \not\in \lambda \ \textnormal{and} \ \lambda \cup \{s\} \ \textnormal{is also a Young diagram} \big\}, \\
\label{RemoveSetFormula} \mathcal{R}_{\lambda} = \big\{ s \in {\mathbb{N}}^2 \colon s \in \lambda \ \textnormal{and} \ \lambda \setminus \{s\} \ \textnormal{is also a Young diagram}\big\}. \end{gather}
It is also convenient to define the outer corner set $\mathcal{R}_{\lambda}^+ = \mathcal{R}_{\lambda} + (1,1)$ as shifts of removable corners.

\label{TheoremMAINRESULT} Let ${\mathcal{L}}$ be the Nazarov--Sklyanin Lax operator in~\eqref{PresentationOfL}. Assume that $\overline{\varepsilon} \in {\mathbb{R}}$ and $\hbar>0$. Choose {non-zero} ${\varepsilon}_1, {\varepsilon}_2 \in {\mathbb{C}}$ parametrizing $\overline{\varepsilon}$, $\hbar$ by the formulas~\eqref{EBarFormula} and~\eqref{HBarFormula}.
\begin{enumerate}\itemsep=0pt
\item[$(1)$] The degree $n$ component $F[w]_n$ of the graded ring $F[w]$ in~\eqref{HDefinition} has a cyclic decomposition 
\begin{equation} \label{TheoremStatementDirectSum}
F[w]_n {\ = \ } \bigoplus_{| \lambda|=n} Z(j_{\lambda}, {\mathcal{L}})
\end{equation}
as a direct sum of finite-dimensional ${\mathcal{L}}$-cyclic subspaces $Z(j_{\lambda},{\mathcal{L}})$ indexed by parti\-tions $\lambda$ of size $n$ and generated by Jack polynomials $j_{\lambda} \in F$ defined in~\eqref{JackPolynomialPresentation}.
\item[$(2)$] The restrictions of ${\mathcal{L}}$ to the subspaces $Z_{\lambda} = Z(j_{\lambda}, {\mathcal{L}})$ in~\eqref{TheoremStatementDirectSum} all have simple spectrum
\begin{equation}
\label{TheoremStatementSimpleSpectrum} {\textnormal{spec}} \big ({\mathcal{L}} \big|_{Z_{\lambda}} \big ) = \big \{ [s] \colon s \in \mathcal{A}_{\lambda}\big \}
\end{equation}
given by the {anisotropic} contents~\eqref{ContentDefinition} of the addable corner set $\mathcal{A}_{\lambda}$ defined above in~\eqref{AddSetFormula}. {In particular, each cyclic subspace $Z_{\lambda}$ in~\eqref{TheoremStatementDirectSum} has dimension $\dim Z_{\lambda} = | \mathcal{A}_{\lambda}|$.}
\item[$(3)$] {As a distinguished vector space basis $\psi_{\lambda}^s$ for} the cyclic spaces $Z(j_{\lambda}, {\mathcal{L}})$ in~\eqref{TheoremStatementDirectSum}, one can choose the unique polynomials $\psi_{\lambda}^s \in F[w]$ {in the variables $w, V_1, V_2, \ldots$} indexed {by addable corners} $s \in \mathcal{A}_{\lambda}$ which are both eigenfunctions of ${\mathcal{L}}$ with eigenvalues $[s]$ as in~\eqref{TheoremStatementSimpleSpectrum}, namely
\[
{\mathcal{L}} \psi_{\lambda}^s = [s] \psi_{\lambda}^s,
\]
{and which project to the Jack polynomial $j_{\lambda}$ for all $s \in \mathcal{A}_{\lambda}$ upon setting $w=0$, namely}
\begin{equation} \label{PsiNormalizationConditionTheoremStatement}
\pi_0 \psi_{\lambda}^s = j_{\lambda},
\end{equation}
 where $\pi_0\colon F[w] \rightarrow F$ is evaluation at $w=0$. In this normalization,
 \begin{equation} \label{JackSuperpositionTheoremStatement}
 j_{\lambda} = \sum_{s \in \mathcal{A}_{\lambda}} \tau_{\lambda}^s \psi_{\lambda}^s,
 \end{equation}
 where $\tau_{\lambda}^s>0$ are weights of the anisotropic transition measure \textnormal{\cite{Ke4}} defined explicitly by \begin{equation} \label{TauPresentation} \tau_{\lambda}^s = \frac{ \prod\limits_{r \in \mathcal{R}^+_{\lambda}} \ \ [s-r] }{ \prod\limits_{ t \in \mathcal{A}_{\lambda} \setminus \{s\}} [s - t] \ \ } \end{equation} for $\mathcal{R}_{\lambda}$ the removable corner set~\eqref{RemoveSetFormula} and $\mathcal{R}_{\lambda}^+ = \mathcal{R}_{\lambda}+(1,1)$ the set of outer corners.
\end{enumerate}

\label{NSTheorem}
Choose ${\varepsilon}_1, {\varepsilon}_2 \in {\mathbb{C}}$ which parametrize $\overline{\varepsilon} \in {\mathbb{R}}$ and $\hbar >0$ by the formulas~\eqref{EBarFormula} and~\eqref{HBarFormula}. For $u \in {\mathbb{C}} \setminus {\mathbb{R}}$, consider the bounded transfer operators
\begin{equation}\label{NSTransferOperatorsPresentationIntro} \mathcal{T}(u) = \pi_0 (u - {\mathcal{L}})^{-1} \colon \ F \rightarrow F, \end{equation}
 which encode all unbounded operators in the hierarchy $\mathcal{T}_{\ell} = \pi_0 {\mathcal{L}}^{\ell}$ as coefficients of $u^{-\ell-1}$.
\begin{itemize}\itemsep=0pt
\item[$(1^{\vee})$] The transfer operators~\eqref{NSTransferOperatorsPresentationIntro} commute in $F$ for distinct values of $u$ and are simultaneously diagonalized on Jack polynomials $j_{\lambda}$ in~\eqref{JackPolynomialPresentation} with eigenvalues $T_{\lambda}(u) \in {\mathbb{C}}$ as in \begin{equation} \label{JacksFromNS} \mathcal{T}(u) \ j_{\lambda} = T_{\lambda}(u) \ j_{\lambda} .\end{equation}
\item[$(2^{\vee})$] The eigenvalues $T_{\lambda}(u) \in {\mathbb{C}}$ in~\eqref{JacksFromNS} are determined by the {anisotropic} contents~\eqref{ContentDefinition} of the elements of the Young diagram $\lambda$ in~\eqref{DefinitionDLambda} and their shifts by the product formula
\begin{equation*}                                  
T_{\lambda}(u)= u^{-1} \cdot \prod_{s \in \lambda}\frac{(u-[s+(0,0)])(u-[s+(1,1)])}{(u-[s+(1,0)])(u-[s+(0,1)])}.
\end{equation*}

Equivalently, if $\mathcal{A}_{\lambda}$ and $\mathcal{R}_{\lambda}$ are the addable and removable corner sets in~\eqref{AddSetFormula} and~\eqref{RemoveSetFormula}, 
\begin{equation}
\label{TEigenvalueAddRemoveStyle} T_{\lambda}(u) = \frac{\prod\limits_{r \in \mathcal{R}^+_{\lambda}} (u - [r]) }{ \prod\limits_{s \in \mathcal{A}_{\lambda} } (u - [s])} , \end{equation}
 where $\mathcal{R}_{\lambda}^+ = \mathcal{R}_{\lambda}+(1,1)$ is the set of outer corners.
 \end{itemize}

\label{JackLaxSpacesAreFiniteDim}The graded components $F[w]_n$ of $F[w]$ have dimension
\begin{equation} \label{HComponentDimensionFormula}
\dim F[w]_n= \sum_{l=0}^n \mathsf{p}(l),
\end{equation}
where $\mathsf{p}(l)$ is the number of partitions of $l$.

\label{PsiPrincipalSpecializationFormula} For $\lambda$ with $| \lambda|=n$, let $\psi_{\lambda}^s (w, V_1, V_2, \ldots, V_{n})$ be the polynomial eigenfunction of ${\mathcal{L}}$ with eigenvalue $[s]$ normalized by $\pi_0 \psi_{\lambda}^s = j_{\lambda}$. Fix $z \in {\mathbb{C}}$. Then
\begin{gather} \label{PsiPrincipalSpecializationW0}
\psi_\lambda^s(0, z, z, \ldots, z) = \prod_{t \in \lambda} (z + [t]), \\
\label{PsiPrincipalSpecializationW1} \psi_\lambda^s(1, z, z, \ldots, z)= \prod_{t \in (\lambda \cup s)^{\times}} (z + [t])
\end{gather}
are two content product formulae for principal specializations at $w=0$ and $w=1$, respectively.

ince $\pi_0 \psi_{\lambda}^s = j_{\lambda}$, the $w=0$ principal specialization formula~(\ref{PsiPrincipalSpecializationW0}) is an immediate consequence of the well-known principal specialization result for $J_{\lambda}$ due to Stanley~\cite{Stanley}. To prove~(\ref{PsiPrincipalSpecializationW1}), let ${\mathcal{L}}\equiv{\mathcal{L}}_{\overline{\varepsilon},\hbar}$ be the Lax operator in~(\ref{PresentationOfL}), with the choices~(\ref{EBarFormula}) and~(\ref{HBarFormula}). The eigenvalue equation is \begin{equation} \label{Pi0Me} {\mathcal{L}}_{\overline{\varepsilon},\hbar} \psi_{\lambda}^s= [s] \psi_{\lambda}^s. \end{equation}
Taking $\pi_0$ of both sides of~(\ref{Pi0Me}), one can use $\pi_0 \psi_{\lambda}^s = j_{\lambda}$ on the right side, then observe that we can replace $\pi_0 {\mathcal{L}}_{\overline{\varepsilon},\hbar}$ by $\pi_0 {\mathcal{L}}_{0,0}$ on the left side. Indeed, by inspecting the terms in~(\ref{PresentationOfL}) with~$\hbar$ and~$\overline{\varepsilon}$, one has $ \pi_0 {\mathcal{L}}_{\overline{\varepsilon},\hbar} \eta = \pi_0 {\mathcal{L}}_{0,0} \eta$ for any $\eta \in F[w]$. As a consequence,
\begin{equation} \label{ConsequencePi0}
\pi_0 {\mathcal{L}}_{0, 0} \psi_{\lambda}^s = [s] j_{\lambda}.
 \end{equation}
 Since $\pi_0 {\mathcal{L}}_{0,0} = \sum_{k=1}^{\infty} V_k \pi_0 w^{-k}$, if we expand our eigenfunction as
 \begin{equation} \label{PsiWPowerExpansion}
 \psi_{\lambda}^s = \sum_{l=0}^{n} ( \pi_{l} \psi_{\lambda}^s) w^l
 \end{equation}
 with each $ \pi_{l} \psi_{\lambda}^s \in F = {\mathbb{C}}[V_1, V_2, \ldots]$ homogeneous of degree $n - l$,~(\ref{ConsequencePi0}) reads
\begin{equation} \label{Arrival} V_1 \pi_1 \psi_{\lambda}^s + V_2 \pi_2 \psi_{\lambda}^s + \cdots + V_n \pi_n \psi_{\lambda}^s = [s] j_{\lambda}(V_1, V_2, \ldots, V_n).
\end{equation}
On the other hand, the difference $\psi_{\lambda}^s(1) - \psi_{\lambda}^s(0)$ between $\psi_{\lambda}^s$ at $w=1$ and $w=0$ is \begin{equation} \label{W1EvalArrive} \pi_1 \psi_{\lambda}^s + \pi_2 \psi_{\lambda}^s + \cdots + \pi_n \psi_{\lambda}^s = \psi_{\lambda}^s (1, V_1, V_2, \ldots, V_n) - j_{\lambda} (V_1, V_2, \ldots, V_n).\end{equation}
Equation~(\ref{Arrival}) is an equality of polynomials in $V_k$ which are homogeneous of degree $n$, whereas equation~(\ref{W1EvalArrive}) is an equality of polynomials in $V_k$ which are not homogeneous. If we evaluate~$V_k = z$ for all $1 \leq k \leq n$ in both~(\ref{Arrival}) and~(\ref{W1EvalArrive}) and assume $z \neq 0$, the left sides of each differ by an overall factor of $z$, so we can conclude that
\begin{equation}
\label{PlopStanley} \psi_{\lambda}^s (1, z, z, \ldots, z) = \left ( 1 + \frac{[s]}{z} \right ) \cdot j_{\lambda}(z, z, \ldots, z) .
\end{equation}
Substituting Stanley's result~(\ref{PsiPrincipalSpecializationW0}) into~(\ref{PlopStanley}) yields~(\ref{PsiPrincipalSpecializationW1}).

he following argument is standard both in the theory of Jacobi matrices and in the study of lattice paths, see, e.g.,~\cite[Lemma 6.3.2]{Ke1}. However, this result is usually presented in the context of a choice of a tridiagonal matrix representation of $L$ and assuming that $L$ is self-adjoint, neither of which is necessary for the argument below. Since $a=0$, $u^{-2} \Pi_J L J = 0$. Expanding the resolvent using a geometric series,~(\ref{TUDefinition}) becomes
\begin{equation} \label{ExpandOleFaithful} T(u) J=u^{-1} J+ \sum_{\ell=2}^{\infty} u^{-\ell-1} \Pi_J L^{\ell} J. \end{equation}
For terms in~(\ref{ExpandOleFaithful}) with $\ell \geq 2$, use~(\ref{WDecomposition}) to insert $\ell-1$ copies of $\textnormal{Id}_W = \Pi_J + {\widetilde{\Pi}}$ between the $\ell$ copies of $L$ which appear in the expansion of $L^{\ell}$. This produces $2^{\ell-1}$ terms of the form $\Pi_J \Pi_1 L \Pi_2 L \Pi_3 \cdots L \Pi_{\ell-1} L J$ with each $\Pi_i \in \big\{\Pi_J, {\widetilde{\Pi}}\big\}$. Group these terms by the minimum value of $i$ so that $\Pi_i = \Pi_J$. Since $a=0$, we can assume $i \geq 2$. After relabeling indices, one checks~(\ref{ExpandOleFaithful}) becomes $T(u) = u^{-1} + u^{-1} {\widetilde{T}}(u) T(u)$ with ${\widetilde{T}}(u)$ as defined in~(\ref{TTildeUDefinition}).

\label{COROLLARYhittingtimecramer} If $a=0$ in~\eqref{JTildeDefinition}, the function ${\widetilde{T}}(u)$ defined for $u \not\in {\textnormal{spec}}\big({\widetilde{L}}\big)$ by~\eqref{TTildeUDefinition} is
\begin{equation*}                                   
{\widetilde{T}}(u) = u - \frac{ \det (u-L)}{ \det \big(u-{\widetilde{L}}\big)}
\end{equation*}
a rational function with poles at ${\textnormal{spec}}\big({\widetilde{L}}\big)$.

\label{GeneralSpectralTheorem} Let $L$, ${\widetilde{L}}$ be the self-adjoint operators in $W$, ${\widetilde{W}}$ of dimensions $m+1$, $m$ with cyclic vectors $J$, ${\widetilde{J}}$ as in Appendix~\textnormal{\ref{SUBSECassumeselfadjoint}}. Then $L$, ${\widetilde{L}}$ have real eigenvalues {$\sigma^{(i)}$, $\widetilde{\sigma}^{(i)}$} which are simple and strictly interlacing
\[
\sigma^{(m)} < \widetilde{\sigma}^{(m)} < \sigma^{(m-1)} < \cdots < \widetilde{\sigma}^{(2)} < \sigma^{(1)} < \widetilde{\sigma}^{(1)} < \sigma^{(0)}.
\]
{Since the spectrum is simple, there exist bases $\big\{\psi^{(i)}\big\}_{i=0}^{m}$, $\big\{ \widetilde{\psi}^{(i)} \big\}_{i=1}^m$ of the cyclic spaces} $W$, ${\widetilde{W}}$, {which are} $L$, ${\widetilde{L}}$ eigenvectors
\begin{gather}
L \psi^{(i)} = \sigma^{(i)} \psi^{(i)}, \label{PreliminaryLEigenvector} \\
{\widetilde{L}} \widetilde{\psi}^{(i)} = \widetilde{\sigma}^{(i)} \widetilde{\psi}^{(i)} \label{PreliminaryLTildeEigenvector}
\end{gather}
{defined uniquely up to complex rescaling of each eigenvector. In fact, the normalizations of each eigenvector can be fixed by the canonical constraints}
\begin{gather} \label{FirstJNormalizationCondition}
\Pi_J \psi^{(i)} = J, \\ \label{SecondJNormalizationCondition} \Pi_J L \widetilde{\psi}^{(i)} = J .
\end{gather}

y the Cauchy interlacing theorem -- e.g.,~\cite[p. 242]{HornJohnsonBOOK} or~\cite[Section~6]{Ke1} -- it remains to prove~(\ref{FirstJNormalizationCondition}) and~(\ref{SecondJNormalizationCondition}). For any basis of $L$ eigenvectors $\psi^{(i)}$, since $\Pi_J$ projects onto ${\mathbb{C}} J$,
\begin{equation} \label{GammaFormula}
\Pi_J \psi^{(i)}= \gamma^{(i)} J
\end{equation}
for some $\gamma^{(i)} \in {\mathbb{C}}$ for all $i \in \{0,1,\ldots, m\}$. We first argue that $\gamma^{(i)}= 0$ is not possible in~(\ref{GammaFormula}), i.e., $\Pi_J \psi^{(i)} \neq 0$. Pairing~(\ref{GammaFormula}) with $J$, using the inner product and  the fact that the orthogonal projection $\Pi_J$ is self-adjoint, one arrives at the identity
\begin{equation} \label{LookAtThis}
\langle J, \psi^{(i)} \rangle = \gamma^{(i)} \| J\|^2.
\end{equation}
As a consequence, if we expand $J$ in the $\psi^s$ basis, formula~(\ref{LookAtThis}) determines the coefficients
\begin{equation} \label{ProdMeBrah}
J = \sum_{i = 0}^m \Bigg ( \gamma^{(i)} \frac{ \| J \|^2}{ \big\| \psi^{(i)}\big\|^2} \Bigg ) \psi^{(i)}.
\end{equation}
Since $J$ is cyclic for $L$ in $W$, its coefficients in the $\psi^{(i)}$ basis {are} non-zero for all $i \in \{0,1,\ldots, m\}$, thus~(\ref{ProdMeBrah}) guarantees $\gamma^{(i)} \neq 0$ for all $i \in \{0,1,\ldots, m\}$. Since the eigenvalues $\sigma^{(i)}$ of $L$ in $W$ are distinct, the $\psi^{(i)}$ are uniquely determined up to overall factors in ${\mathbb{C}}^{\times}$, so we can choose these factors uniquely so $\gamma^{(i)} = 1$ in~(\ref{GammaFormula}), proving~(\ref{FirstJNormalizationCondition}). By Proposition~\ref{PROPsecondcyclicspace}, ${\widetilde{L}}$ is cyclic in ${\widetilde{W}} = ({\mathbb{C}} J)^{\perp}$. Since ${\widetilde{L}} = {\widetilde{L}}^{\dagger}$, the same argument {above repeated in ${\widetilde{W}}$ instead of $W$, this time choosing \smash{$\widetilde{\gamma}^{(i)} =   \| J\|^2/ \| {\widetilde{J}} \|^2 $} instead of $\gamma^{(i)} = 1$, guarantees} that if we consider ${\widetilde{J}} \in {\widetilde{W}}$ in~(\ref{JTildeDefinition}), there is a unique basis $\widetilde{\psi}^{(i)}$ of ${\widetilde{L}}$-eigenvectors of ${\widetilde{W}}$ with
\begin{equation} \label{MiddleManFixa}
\Pi_{{\widetilde{J}}} \widetilde{\psi}^{(i)} = \frac{\|J\|^2}{\big\| {\widetilde{J}}\big\|^2} {\widetilde{J}} .
\end{equation}
{Pairing both sides of~(\ref{MiddleManFixa}) with ${\widetilde{J}}$ and using the fact that the orthogonal projection $\Pi_{{\widetilde{J}}}$ to ${\mathbb{C}} {\widetilde{J}}$ is self-adjoint,~(\ref{MiddleManFixa}) implies
\begin{equation} \label{RevisedPaperEXHIBITA}
\big\langle {\widetilde{J}} , \widetilde{\psi}^{(i)} \big\rangle = \| J \|^2 .
\end{equation} At the same time, since ${\widetilde{J}} = {\widetilde{\Pi}} L J$ holds by~(\ref{JTildeDefinition}), $L^{\dagger} = L$, ${\widetilde{\Pi}} = {\widetilde{\Pi}}^{\dagger}$, and ${\widetilde{\Pi}} \widetilde{\psi}^{(i)} = \widetilde{\psi}^{(i)}$, we also have
\begin{equation} \label{RevisedPaperEXHIBITB}
\big\langle {\widetilde{J}}, \widetilde{\psi}^{(i)} \big\rangle = \big\langle {\widetilde{\Pi}} L J, \widetilde{\psi}^{(i)} \big\rangle = \big\langle J , L {\widetilde{\Pi}} \widetilde{\psi}^{(i)} \big\rangle = \big\langle J , L \widetilde{\psi}^{(i)} \big\rangle.
\end{equation}
 Equating~(\ref{RevisedPaperEXHIBITA}) and~(\ref{RevisedPaperEXHIBITB}) implies} $\frac{ \langle {J} , L\widetilde{\psi}^{(i)} \rangle}{ \langle J, J \rangle } = 1$ which is equivalent to~(\ref{SecondJNormalizationCondition}).

Let $\psi^{(i)}$, $\widetilde{\psi}^{(i)}$ be the sets of eigenvectors of the self-adjoint operators $L$, ${\widetilde{L}}$ normalized with respect to the cyclic vector $J$ by the conditions \eqref{FirstJNormalizationCondition} and \eqref{SecondJNormalizationCondition}. Let $\tau^{(i)}$, $\widetilde{\tau}^{(i)}$ be the residues in \eqref{TauDefinition} and \eqref{TauTildeDefinition} of the rational functions $T(u)$, ${\widetilde{T}}(u)$ in \eqref{TUinnerproductDefinition} and~\eqref{TTildeUinnerproductDefinition}. Then
\begin{gather}
\tau^{(i)} \| \psi^{(i)}\|^2 = \|J\|^2, \label{PsiNormFormula}\\
\widetilde{\tau}^{(i)} \| \widetilde{\psi}^{(i)} \|^2 = \| J\|^2.\label{PsiTildeNormFormula}
\end{gather} In particular, {the residues $\tau^{(i)}$ and $\widetilde{\tau}^{(i)}$} in \eqref{TauDefinition} and \eqref{TauTildeDefinition} are {all} positive.

resolutions of identities $\textnormal{Id}_W$, $\textnormal{Id}_{{\widetilde{W}}}${, we have}
\begin{gather} \label{ReturnOfTheMack} J = \sum_{i= 0}^{m} \Pi_{\psi^{(i)}} J = \sum_{i=0}^m \frac{\big\langle \psi^{(i)}, J \big\rangle }{ \big\| \psi^{(i)} \big\|^2 } \psi^{(i)}, \\
\label{ReturnOfTheMackTILDE}{\widetilde{J}} = \sum_{i=1}^m \Pi_{\widetilde{\psi}^{(i)}} {\widetilde{J}} = \sum_{i=1}^m \frac{\big\langle \widetilde{\psi}^{(i)}, {\widetilde{J}} \big\rangle }{ \big\| \widetilde{\psi}^{(i)} \big\|^2 } \widetilde{\psi}^{(i)}.
\end{gather}

 {Substituting~(\ref{ReturnOfTheMack}) and~(\ref{ReturnOfTheMackTILDE}) into the inner product formulas~(\ref{TUinnerproductDefinition}) and~(\ref{TTildeUinnerproductDefinition}) for $T$, ${\widetilde{T}}$, one may use the eigenvalue equations~(\ref{PreliminaryLEigenvector}) and~(\ref{PreliminaryLTildeEigenvector}) and the orthogonality of eigenfunctions to get}
\begin{gather}
T(u) = \frac{1}{\| J\|^2} \sum_{i=0}^m \frac{1}{u - \sigma^{(i)} } \cdot \frac{ \big| \big\langle J, \psi^{(i)} \big\rangle \big|^2}{ \big\| \psi^{(i)} \big\|^2}, \label{TResolved} \\
\label{TTildeResolved} {\widetilde{T}}(u) = \frac{1}{\| J\|^2} \sum_{i=0}^m \frac{1}{u - \widetilde{\sigma}^{(i)} } \cdot \frac{ \big| \big\langle {\widetilde{J}}, \widetilde{\psi}^{(i)} \big\rangle \big|^2}{\big \| \widetilde{\psi}^{(i)} \big\|^2}.
\end{gather}
 {Taking residues of~(\ref{TResolved}) and~(\ref{TTildeResolved}) at eigenvalues $\sigma^{(i)}$, $\widetilde{\sigma}^{(i)}$ gives
\begin{gather}
\tau^{(i)} = \frac{1}{\| J\|^2} \cdot \frac{ \big| \big\langle J, \psi^{(i)} \big\rangle \big|^2}{ \big\| \psi^{(i)} \big\|^2}, \label{TausResolved}\\
\widetilde{\tau}^{(i)} = \frac{1}{\| J\|^2} \cdot \frac{ \big| \big\langle {\widetilde{J}}, \widetilde{\psi}^{(i)} \big\rangle \big|^2}{ \big\| \widetilde{\psi}^{(i)} \big\|^2}.\label{TauTildesResolved}
\end{gather}
 Finally, since the} normalization conditions~(\ref{FirstJNormalizationCondition}) and~(\ref{SecondJNormalizationCondition}) and $L = L^{\dagger}$ imply
\begin{gather}
\big\langle J, \psi^{(i)} \big\rangle = \| J\|^2, \label{JPsiInnerProduct}\\
\big\langle {\widetilde{J}}, \widetilde{\psi}^{(i)} \big\rangle = \| J\|^2, \label{JTildePsiTildeInnerProduct}
\end{gather}
 {substituting~(\ref{JPsiInnerProduct}) and~(\ref{JTildePsiTildeInnerProduct}) into~(\ref{TausResolved}) and~(\ref{TauTildesResolved}) completes the proof.}

\label{PROPResiduesInSuperpositions} In the self-adjoint case, the residues {$\tau^{(i)}$ and $\widetilde{\tau}^{(i)}$} of $T$ and ${\widetilde{T}}$ arise as coefficients in the expression of the cyclic vectors $J$ and ${\widetilde{J}}$ as linear combinations of eigenvectors of~$L$ and~${\widetilde{L}}$
\begin{gather}
J = \sum_{i=0}^m \tau^{(i)} \psi^{(i)}, \label{JAsSuperposition}\\
{\widetilde{J}} = \sum_{i =1}^m \widetilde{\tau}^{(i)} \widetilde{\psi}^{(i)}\label{JTildeAsSuperposition}
\end{gather}
assuming that $\psi^{(i)}$ and $\widetilde{\psi}^{(i)}$ are normalized by the conditions~\eqref{FirstJNormalizationCondition} and \eqref{SecondJNormalizationCondition}.

Let $\psi^{(i)}$ and $\widetilde{\psi}^{(i)}$ be eigenvectors of self-adjoint operators $L$ and ${\widetilde{L}}$ normalized with respect to the cyclic vector $J$ by the conditions \eqref{FirstJNormalizationCondition} and \eqref{SecondJNormalizationCondition} with corresponding eigenvalues $\sigma^{(i)}$ and $\widetilde{\sigma}^{(i)}$. Then, assuming $a=0$ in \eqref{JTildeDefinition} so that $LJ = {\widetilde{J}}$, the eigenvectors of $L$ and~${\widetilde{L}}$ satisfy
\begin{gather}
\label{KerovFormulaForPsiTilde} \widetilde{\psi}^{(i)} = \frac{1}{L-\widetilde{\sigma}^{(i)}} J, \\
\label{KerovFormulaForPsi} \psi^{(i)} = J + \frac{1}{\sigma^{(i)} - {\widetilde{L}}} {\widetilde{J}} .
\end{gather}

e first prove~(\ref{KerovFormulaForPsiTilde}). To begin, we observe that \begin{equation} \label{ThisExpressionLivesInWTilde} \Pi_J \frac{1}{ L - \widetilde{\sigma}} J = 0 \end{equation} since~(\ref{TUDefinition}) implies that the left-hand side of~(\ref{ThisExpressionLivesInWTilde}) is $-T(\widetilde{\sigma}^t) J$, but we know that $T(\widetilde{\sigma}^t)=0$ since \smash{$\widetilde{\sigma}^{(i)} \in {\textnormal{spec}}\big({\widetilde{L}}\big)$} is necessarily a zero of the rational function $T$ by Proposition~\ref{PROPcramer}. As a~consequence of~(\ref{ThisExpressionLivesInWTilde}), \smash{${\widetilde{\Pi}} \frac{1}{ L - \widetilde{\sigma}^{(i)} } J = \frac{1}{ L - \widetilde{\sigma}^{(i)} } J $} which implies the eigenvalue relation
\[ {\widetilde{L}} \frac{1}{L - \widetilde{\sigma}^{(i)} } J = {\widetilde{\Pi}} L {\widetilde{\Pi}} \frac{1}{L - \widetilde{\sigma}^{(i)}} J = {\widetilde{\Pi}} \big(L- \widetilde{\sigma}^{(i)} + \widetilde{\sigma}^{(i)}\big) \frac{1}{ L - \widetilde{\sigma}^{(i)}} J = \widetilde{\sigma}^{(i)} \frac{1}{L - \widetilde{\sigma}^{(i)} } J . \]
Finally, since formula~(\ref{ThisExpressionLivesInWTilde}) also implies that \smash{$\Pi_J L \frac{1}{ L - \widetilde{\sigma}^{(i)}} J = \Pi_J J + \widetilde{\sigma}^{(i)} \Pi_J \frac{1}{ L - \widetilde{\sigma}^{(i)} } J = J$}, we have shown that \smash{$\frac{1}{L - \widetilde{\sigma}^{(i)}} J$} is an ${\widetilde{L}}$-eigenvector with eigenvalue $\widetilde{\sigma}^{(i)}$ satisfying~(\ref{SecondJNormalizationCondition}). Since these properties uniquely characterize $\widetilde{\psi}^{(i)}$, we have proven~(\ref{KerovFormulaForPsiTilde}). Next, we prove~(\ref{KerovFormulaForPsi}) assuming $a=0$ so that $LJ = {\widetilde{J}}$ in~(\ref{JTildeDefinition}). To begin, the resolvent of ${\widetilde{L}}$ is well defined at $u=\sigma^{(i)}$ since in Theorem~\ref{GeneralSpectralTheorem} we have seen that ${\textnormal{spec}}(L) \cap {\textnormal{spec}}\big({\widetilde{L}}\big)= \varnothing$. As a consequence, ${\widetilde{J}} \in {\widetilde{W}}$ implies that $\frac{1}{\sigma^{(i)} - {\widetilde{L}}} {\widetilde{J}} \in {\widetilde{W}}$, hence the vector on the right-hand side of~(\ref{KerovFormulaForPsi}) satisfies \[ \Pi_J \Bigg ( J + \frac{1}{\sigma^{(i)} - {\widetilde{L}}} {\widetilde{J}} \Bigg ) = J \]
 the normalization condition~(\ref{FirstJNormalizationCondition}). To verify that this vector is indeed an $L$-eigenvector with eigenvalue $\sigma^{(i)}$, multiply by $L$ then calculate its projections onto ${\mathbb{C}} J$ and ${\widetilde{W}} = ( {\mathbb{C}} J)^{\perp}$. In the~${\mathbb{C}} J$ projection, we can simplify using our assumption $a=0$ in~(\ref{JTildeDefinition}), the definition~(\ref{TTildeUDefinition}) of ${\widetilde{T}}(u)$, and ${\widetilde{T}}\big(\sigma^{(i)}\big) = \sigma^{(i)}$ at the special value $u = \sigma^{(i)}$ due to Corollary~\ref{COROLLARYhittingtimecramer}:
 \begin{equation} \label{PiJOfLTimesRHS}
 \Pi_J L \Bigg ( J + \frac{1}{\sigma^{(i)} - {\widetilde{L}}} {\widetilde{J}} \Bigg ) = \Pi_J L J + \Pi_J L \frac{1}{\sigma^{(i)} - {\widetilde{L}}} {\widetilde{J}} = a J + T\big(\sigma^{(i)}\big) J = \sigma^s J.
 \end{equation} In the ${\widetilde{W}} = ({\mathbb{C}} J)^{\perp}$
 projection, using $\frac{1}{\sigma^{(i)} - {\widetilde{L}}} {\widetilde{J}} \in {\widetilde{W}}$, ${\widetilde{\Pi}} L {\widetilde{\Pi}} = {\widetilde{L}}$, and ${\widetilde{L}} = -\big({\sigma^{(i)}} - {\widetilde{L}}\big) + \sigma^{(i)}$,
\begin{gather}
{\widetilde{\Pi}} L \Bigg ( J + \frac{1}{\sigma^{(i)} - {\widetilde{L}}} {\widetilde{J}} \Bigg ) = {\widetilde{\Pi}} L J + {\widetilde{L}} \frac{1}{\sigma^{(i)} - {\widetilde{L}}} {\widetilde{J}}= {\widetilde{J}} - {\widetilde{J}} + \sigma^{(i)} \frac{1}{\sigma^{(i)} - {\widetilde{L}}} {\widetilde{J}} \nonumber\\
\hphantom{{\widetilde{\Pi}} L \Bigg ( J + \frac{1}{\sigma^{(i)} - {\widetilde{L}}} {\widetilde{J}} \Bigg )}{}= \sigma^{(i)} \frac{1}{\sigma^{(i)} - {\widetilde{L}}} {\widetilde{J}}. \label{PiTildeOfLTimesRHS}
\end{gather}
Since~(\ref{PiJOfLTimesRHS}) and~(\ref{PiTildeOfLTimesRHS}) are $\sigma^{(i)}$ times the same projections of $J+ \frac{1}{ \sigma^{(i)} - {\widetilde{L}}} {\widetilde{J}}$,~(\ref{KerovFormulaForPsi}) follows.
